// Package icons embeds the lucide icons the views draw (generated by scripts/gen-icons.mjs).
package icons

import (
	"embed"
	"sync"

	"github.com/egoist/mygo/ui"
)

//go:embed *.svg
var files embed.FS

var cache sync.Map

// Get returns the icon of name (a lucide name such as "languages"). It panics on an unknown name, which a
// test catches.
func Get(name string) *ui.SVG {
	if v, ok := cache.Load(name); ok {
		return v.(*ui.SVG)
	}
	data, err := files.ReadFile(name + ".svg")
	if err != nil {
		panic("icons: no icon " + name)
	}
	svg := ui.MustParseSVG(data)
	cache.Store(name, svg)
	return svg
}

// Names lists the embedded icons.
func Names() []string {
	entries, _ := files.ReadDir(".")
	out := make([]string, 0, len(entries))
	for _, e := range entries {
		out = append(out, e.Name()[:len(e.Name())-len(".svg")])
	}
	return out
}
